#!/usr/bin/env python3
"""
Oxysintx — Port Scanner v4.0.0 (Professional Grade)

Ultra-fast TCP connect scanner with wordlist-driven port loading.

Scan modes
──────────
  • BASIC   — reads port files port2.txt through port1000.txt from
              the porttxt folder. Falls back to built-in 1-1000 range
              if the folder is empty (so the app never hard-fails).
  • EXPERT  — reads every port*.txt file (any numeric suffix), no cap
              on the file number.

Scan techniques
───────────────
  • TCP connect      (default, no privileges needed)
  • UDP probe        (opt-in via --udp; best-effort, no root required)
  • Banner grabbing  (opt-in via --banner; TCP services)
  • TLS probe        (opt-in via --tls; 443/8443/9443/etc.)
  • Reverse DNS      (opt-in via --rdns; only for open ports)

Core features
─────────────
  • Persistent 400-thread pool reused across scans
  • Adaptive worker scaling on thread-exhaustion recovery
  • TCP_NODELAY + SO_LINGER=RST → zero TIME_WAIT accumulation
  • Explicit socket close → no FD leaks under load
  • Rate limiting (token bucket)
  • Per-phase timeouts (connect / banner / TLS)
  • Multi-format export: JSON / CSV / Nmap-style XML / SARIF
  • Streaming API (SSE-friendly) for real-time UIs
  • Batch scanning across many targets
  • Progress callback (done, total, current port)
  • Port state classification: open / closed / filtered
  • Rich service database with 300+ entries
  • Isolated logger — no duplication with Flask/root handlers
  • Backward compatible — same run(target, mode) orchestrator signature

Author: Yanxzyx
Version: 4.0.0
"""

from __future__ import annotations

import argparse
import atexit
