from urllib.parse import urlparse


# ═══════════════════════════════════════════════════════════════════════════
# LOGGING
# ═══════════════════════════════════════════════════════════════════════════
logger = logging.getLogger("oxysintx.port_scan")
logger.propagate = False
if not logger.handlers:
    _h = logging.StreamHandler()
    _h.setFormatter(logging.Formatter(
        "%(asctime)s [%(levelname)s] %(name)s: %(message)s",
        datefmt="%Y-%m-%d %H:%M:%S",
    ))
    logger.addHandler(_h)
logger.setLevel(logging.INFO)

if not logging.getLogger().handlers:
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
        datefmt="%Y-%m-%d %H:%M:%S",
    )


# ═══════════════════════════════════════════════════════════════════════════
# CONSTANTS
# ═══════════════════════════════════════════════════════════════════════════
MAX_PORT              = 65535
MIN_PORT              = 1
MAX_TOTAL_PORTS       = 65535
DEFAULT_TIMEOUT       = 0.4
DEFAULT_THREADS       = 400
MAX_THREADS           = 500
MIN_THREADS           = 32
DNS_TIMEOUT           = 5.0
BANNER_TIMEOUT        = 1.5
TLS_TIMEOUT           = 3.0
RATE_LIMIT_DEFAULT    = 0.0         # 0 = unlimited
MAX_BANNER_BYTES      = 2048
MAX_RETRIES_FILTERED  = 1           # extra attempt for ports that timed out

# File loading
BASIC_FILE_START      = 2           # port2.txt
BASIC_FILE_END        = 1000        # port1000.txt (inclusive)
BASIC_FALLBACK_RANGE  = (1, 1000)   # only used if folder empty

# TLS-enabled ports for auto TLS probe
TLS_PORTS = {443, 465, 636, 853, 989, 990, 992, 993, 994, 995, 2083, 2087,
             2096, 3269, 4443, 5061, 5986, 6443, 7443, 8443, 9443, 10443,
             16379, 27017, 27018, 27019}

TOOL_INFO = {
    "name": "Port Scan",
    "version": "4.0.0",
    "description": (
        "Ultra-fast TCP connect / UDP port scanner. "
        "BASIC: reads port files port2.txt..port1000.txt from porttxt folder. "
        "EXPERT: reads all port*.txt files. "
        "400 persistent threads, banner grabbing, TLS probe, RDNS, "
        "multi-format export, streaming API."
    ),
    "author": "Yanxzyx",
}


