BASIC_PORTS: List[int] = list(range(1, 1001))
_SO_LINGER_RST = struct.pack("ii", 1, 0)


# ═══════════════════════════════════════════════════════════════════════════
# DATACLASS
# ═══════════════════════════════════════════════════════════════════════════
@dataclass
class ScanResult:
    port: int
    is_open: bool
    service: str = "unknown"
    response_time: float = 0.0
    state: str = "closed"           # open / closed / filtered
    banner: str = ""
    tls_info: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "port": self.port,
            "is_open": self.is_open,
            "service": self.service,
            "response_time": round(self.response_time, 3),
            "state": self.state,
            "banner": self.banner,
            "tls_info": self.tls_info,
        }


# ═══════════════════════════════════════════════════════════════════════════
# THREAD POOL
# ═══════════════════════════════════════════════════════════════════════════
_pool: Optional[concurrent.futures.ThreadPoolExecutor] = None
_pool_workers = 0


def _get_pool(workers: int) -> concurrent.futures.ThreadPoolExecutor:
    global _pool, _pool_workers
    if _pool is None or _pool_workers != workers:
        if _pool is not None:
            _pool.shutdown(wait=False)
        _pool = concurrent.futures.ThreadPoolExecutor(
            max_workers=workers, thread_name_prefix="oxysintx-pscan",
        )
        _pool_workers = workers
    return _pool


def _shutdown_pool() -> None:
    global _pool
    if _pool is not None:
        _pool.shutdown(wait=False)
        _pool = None


atexit.register(_shutdown_pool)


# ═══════════════════════════════════════════════════════════════════════════
# PATH RESOLUTION
# ═══════════════════════════════════════════════════════════════════════════
def _resolve_porttxt_path(folder_hint: Optional[str] = None) -> Path:
    env_path = os.environ.get("PORT_DATA_PATH")
    if env_path:
        c = Path(env_path)
        if c.is_dir():
            return c
    if folder_hint:
        c = Path(folder_hint)
        return c if c.is_absolute() else Path.cwd() / c
    try:
        module_dir = Path(__file__).resolve().parent
        for sibling in (module_dir.parent / "porttxt", module_dir / "porttxt"):
            if sibling.is_dir():
                return sibling
    except (NameError, OSError):
        pass
    for cwd_candidate in (Path.cwd() / "porttxt", Path.cwd() / "Oxysintx" / "porttxt"):
        if cwd_candidate.is_dir():
            return cwd_candidate
    return Path.cwd() / "porttxt"


# ═══════════════════════════════════════════════════════════════════════════
# PORT FILE PARSER
# ═══════════════════════════════════════════════════════════════════════════
def _parse_port_file(fpath: Path, ports: Set[int], cap: List[bool]) -> int:
    count = 0
    try:
        with open(fpath, "r", encoding="utf-8", errors="replace") as fh:
            for line in fh:
                if len(ports) >= MAX_TOTAL_PORTS:
                    cap[0] = True
                    return count
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                for token in line.replace(",", " ").split():
                    token = token.strip()
                    if not token:
                        continue
                    if "-" in token and not token.startswith("-"):
                        try:
                            s, e = token.split("-", 1)
                            si, ei = int(s.strip()), int(e.strip())
                            if si > ei: si, ei = ei, si
                            if MIN_PORT <= si <= MAX_PORT and MIN_PORT <= ei <= MAX_PORT:
                                avail = MAX_TOTAL_PORTS - len(ports)
                                if avail <= 0:
                                    cap[0] = True
                                    return count
                                rp = list(range(si, ei + 1))
                                if len(rp) > avail:
                                    rp = rp[:avail]
                                    cap[0] = True
                                ports.update(rp)
                                count += len(rp)
                                if cap[0]:
                                    return count
                        except ValueError:
                            continue
                    else:
                        try:
                            p = int(token)
                            if MIN_PORT <= p <= MAX_PORT:
                                if len(ports) >= MAX_TOTAL_PORTS:
                                    cap[0] = True
                                    return count
                                ports.add(p)
                                count += 1
                        except ValueError:
                            continue
    except OSError as e:
        logger.debug("[port_scan] cannot read %s: %s", fpath, e)
    return count


# ═══════════════════════════════════════════════════════════════════════════
# PORT LOADERS
# ═══════════════════════════════════════════════════════════════════════════
def load_basic_ports(folder_path: Optional[str] = None) -> Tuple[List[int], Dict[str, Any]]:
    """
    Basic mode: read port files portN.txt for N in [BASIC_FILE_START, BASIC_FILE_END]
    (i.e. port2.txt .. port1000.txt). Falls back to built-in 1-1000 if none found.
    """
    base = _resolve_porttxt_path(folder_path)
    ports: Set[int] = set()
    files_read: List[str] = []
    errors: List[str] = []
    cap = [False]

    if base.is_dir():
        for idx in range(BASIC_FILE_START, BASIC_FILE_END + 1):
            if len(ports) >= MAX_TOTAL_PORTS:
                break
            fpath = base / f"port{idx}.txt"
            if not fpath.is_file():
                continue
            added = _parse_port_file(fpath, ports, cap)
            if added > 0:
                files_read.append(fpath.name)

    if ports:
        return sorted(ports), {
            "directory":        str(base),
            "files_read":       len(files_read),
            "file_names":       files_read,
            "total_ports_loaded": len(ports),
            "capped":           cap[0],
            "source":           "wordlist",
            "errors":           errors,
        }

    # Fallback — built-in 1..1000
    logger.info("[port_scan] no basic port files in %s — fallback to 1-1000", base)
    return BASIC_PORTS.copy(), {
        "directory":        str(base),
        "files_read":       0,
        "file_names":       [],
        "total_ports_loaded": len(BASIC_PORTS),
        "capped":           False,
        "source":           "builtin_fallback",
        "errors":           errors,
    }


def load_ports_from_folder(folder_path: Optional[str] = None) -> Tuple[List[int], Dict[str, Any]]:
    """Expert mode: read every port*.txt in the folder (no numeric cap)."""
    base = _resolve_porttxt_path(folder_path)
    ports: Set[int] = set()
    files_read: List[str] = []
    files_seen: Set[str] = set()
    errors: List[str] = []
    cap = [False]

    if not base.is_dir():
        return [], {
            "directory": str(base), "files_read": 0, "file_names": [],
            "total_ports_loaded": 0, "capped": False,
            "errors": [f"Directory not found: {base}"], "source": "wordlist",
        }

    for idx in range(1, 11):
        if len(ports) >= MAX_TOTAL_PORTS:
            break
        fpath = base / f"port{idx}.txt"
        if not fpath.is_file():
            continue
        files_seen.add(fpath.name)
        if _parse_port_file(fpath, ports, cap) > 0:
            files_read.append(fpath.name)

    if len(ports) < MAX_TOTAL_PORTS:
        for fpath_str in sorted(glob_module.glob(str(base / "port*.txt"))):
            if len(ports) >= MAX_TOTAL_PORTS:
                break
            fpath = Path(fpath_str)
            if not fpath.is_file() or fpath.name in files_seen:
                continue
            files_seen.add(fpath.name)
            if _parse_port_file(fpath, ports, cap) > 0:
                files_read.append(fpath.name)

    return sorted(ports), {
        "directory": str(base), "files_read": len(files_read),
        "file_names": files_read, "total_ports_loaded": len(ports),
        "capped": cap[0], "errors": errors, "source": "wordlist",
    }


# ═══════════════════════════════════════════════════════════════════════════
# TARGET PARSER + DNS
# ═══════════════════════════════════════════════════════════════════════════
def _extract_host(target: str) -> str:
    s = (target or "").strip()
    if not s:
        return ""
    if "://" not in s and s.count(":") >= 2 and not s.startswith("["):
        return s
    candidate = s if "://" in s else "//" + s
    try:
        parsed = urlparse(candidate)
        if parsed.hostname:
            return parsed.hostname
    except ValueError:
        pass
    return (s.replace("https://", "").replace("http://", "")
              .split("/")[0].split("@")[-1].split(":")[0].strip("[]").strip())


def _resolve_target(host: str) -> Tuple[str, int]:
    for fam, _p in ((socket.AF_INET, None), (socket.AF_INET6, None)):
        try:
            socket.inet_pton(fam, host)
            return host, fam
        except (OSError, ValueError):
            continue
    old = socket.getdefaulttimeout()
    try:
        socket.setdefaulttimeout(DNS_TIMEOUT)
        infos = socket.getaddrinfo(host, None, type=socket.SOCK_STREAM)
    finally:
        socket.setdefaulttimeout(old)
    if not infos:
        raise socket.gaierror(f"No addresses found for {host}")
    for fam, _, _, _, sa in infos:
        if fam == socket.AF_INET:
            return sa[0], socket.AF_INET
    fam, _, _, _, sa = infos[0]
    return sa[0], fam


# ═══════════════════════════════════════════════════════════════════════════
# SCANNER
# ═══════════════════════════════════════════════════════════════════════════
class PortScanner:
    def __init__(self, timeout: float = DEFAULT_TIMEOUT,
                 max_workers: int = DEFAULT_THREADS,
                 grab_banner: bool = False,
                 probe_tls: bool = False,
                 resolve_rdns: bool = False,
                 rate_limit: float = RATE_LIMIT_DEFAULT,
                 progress_cb: Optional[Callable[[int, int, int], None]] = None):
        self.timeout = timeout
        self.max_workers = max(MIN_THREADS, min(max_workers, MAX_THREADS))
        self.grab_banner = grab_banner
        self.probe_tls = probe_tls
        self.resolve_rdns = resolve_rdns
        self.rate_limit = rate_limit
        self.progress_cb = progress_cb
        self._rl_lock = threading.Lock()
        self._rl_last = 0.0
        self._rl_progress_lock = threading.Lock()
        self._done = 0
        self._total = 0

    def _throttle(self) -> None:
        if self.rate_limit <= 0:
            return
        with self._rl_lock:
            now = time.monotonic()
            gap = 1.0 / self.rate_limit
            wait = gap - (now - self._rl_last)
            if wait > 0:
                time.sleep(wait)
            self._rl_last = time.monotonic()

    def _emit_progress(self, port: int) -> None:
        if not self.progress_cb:
            return
        with self._rl_progress_lock:
            self._done += 1
            done = self._done
            total = self._total
        try:
            self.progress_cb(done, total, port)
        except Exception:
            pass

    @staticmethod
    def _grab_banner(sock: socket.socket, timeout: float = BANNER_TIMEOUT) -> str:
        try:
            sock.settimeout(timeout)
            data = sock.recv(MAX_BANNER_BYTES)
            if not data:
                return ""
            # Decode printable chars only
            txt = data.decode("utf-8", errors="replace")
            txt = "".join(c if 32 <= ord(c) < 127 else " " for c in txt)
            return " ".join(txt.split())[:200]
        except Exception:
            return ""

    @staticmethod
    def _probe_tls_info(host: str, port: int) -> Dict[str, Any]:
        try:
            ctx = ssl.create_default_context()
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_NONE
            with socket.create_connection((host, port), timeout=TLS_TIMEOUT) as raw:
                with ctx.wrap_socket(raw, server_hostname=host) as ss:
                    cert = ss.getpeercert() or {}
                    return {
                        "protocol": ss.version(),
                        "cipher":   (ss.cipher() or ("",))[0],
                        "subject":  dict(x[0] for x in cert.get("subject", [])),
                        "issuer":   dict(x[0] for x in cert.get("issuer", [])),
                        "not_after": cert.get("notAfter", ""),
                    }
        except Exception:
            return {}

    def _probe(self, host: str, port: int, family: int) -> ScanResult:
        self._throttle()
        start = time.time()
        sock: Optional[socket.socket] = None
        try:
            sock = socket.socket(family, socket.SOCK_STREAM)
            sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
            try:
                sock.setsockopt(socket.SOL_SOCKET, socket.SO_LINGER, _SO_LINGER_RST)
            except (OSError, AttributeError):
                pass
            sock.settimeout(self.timeout)
            sock.connect((host, port))
            elapsed = time.time() - start

            banner = ""
            tls_info: Dict[str, Any] = {}
            service = SERVICES.get(port, "unknown")

            if self.grab_banner and port not in TLS_PORTS:
                banner = self._grab_banner(sock)
                if banner:
                    # Best-effort service name correction
                    low = banner.lower()
                    if low.startswith("ssh-"):
                        service = "SSH"
                    elif "http/" in low:
                        service = "HTTP"

            if self.probe_tls and port in TLS_PORTS:
                tls_info = self._probe_tls_info(host, port)
                if tls_info:
                    service = service or "TLS"

            result = ScanResult(
                port=port, is_open=True, service=service,
                response_time=elapsed, state="open",
                banner=banner, tls_info=tls_info,
            )
        except socket.timeout:
            result = ScanResult(port=port, is_open=False,
                                response_time=self.timeout, state="filtered")
        except (ConnectionRefusedError, ConnectionResetError):
            result = ScanResult(port=port, is_open=False, state="closed")
        except OSError:
            result = ScanResult(port=port, is_open=False, state="closed")
        except Exception:
            result = ScanResult(port=port, is_open=False, state="closed")
        finally:
            if sock is not None:
                try: sock.close()
                except OSError: pass

        self._emit_progress(port)
        return result

    def scan(self, target: str, ports: List[int]
             ) -> Tuple[List[ScanResult], float, int, str, int]:
        if not ports:
            return [], 0.0, 0, target, socket.AF_INET

        resolved_ip, family = _resolve_target(target)

        workers = self.max_workers
        last_error: Optional[BaseException] = None
        self._total = len(ports)
        self._done = 0

        while workers >= MIN_THREADS:
            try:
                logger.info("[port_scan] scanning %d ports on %s (%s) [%d threads]",
                            len(ports), target, resolved_ip, workers)
                pool = _get_pool(workers)
                probe = partial(self._probe, resolved_ip, family=family)
                chunk = max(1, len(ports) // (workers * 4))
                t0 = time.time()
                results = list(pool.map(probe, ports, chunksize=chunk))
                elapsed = time.time() - t0
                open_count = sum(1 for r in results if r.is_open)
                logger.info("[port_scan] done: %d open in %.2fs (%d threads)",
                            open_count, elapsed, workers)
                return results, elapsed, workers, resolved_ip, family
            except (RuntimeError, OSError) as e:
                last_error = e
                nw = workers // 2
                if nw < MIN_THREADS:
                    break
                logger.warning("[port_scan] thread exhaustion at %d — retry %d (%s)",
                               workers, nw, e)
                workers = nw
                time.sleep(0.15)

        raise RuntimeError(
            f"Thread allocation failed ({self.max_workers}→{MIN_THREADS}). "
            f"Last error: {last_error}"
        )


# ═══════════════════════════════════════════════════════════════════════════
# MAIN
# ═══════════════════════════════════════════════════════════════════════════
def run(target: str, mode: str = "basic", **kwargs) -> dict:
    timeout     = float(kwargs.get("timeout", DEFAULT_TIMEOUT))
    max_workers = int(kwargs.get("max_workers", DEFAULT_THREADS))
    folder_path = kwargs.get("folder_path", None)
    verbose     = bool(kwargs.get("verbose", False))
    grab_banner = bool(kwargs.get("banner", False))
    probe_tls   = bool(kwargs.get("tls", False))
    rdns        = bool(kwargs.get("rdns", False))
    rate_limit  = float(kwargs.get("rate_limit", RATE_LIMIT_DEFAULT))
    progress_cb = kwargs.get("progress_cb")

    if verbose:
        logger.setLevel(logging.DEBUG)

    host = _extract_host(target)
    if not host:
        return {
            "tool": "port_scan", "version": TOOL_INFO["version"],
            "target": target, "data": {}, "error": "Empty target.",
        }

    ports_source = "builtin"
    load_metadata: Dict[str, Any] = {}
    ports_to_scan: List[int]

    if mode == "expert":
        file_ports, load_metadata = load_ports_from_folder(folder_path)
        if not file_ports:
            err = (f"No port files found in "
                   f"{load_metadata.get('directory', 'unknown')}. Expert mode "
                   f"requires port*.txt files in the porttxt folder.")
            logger.error("[port_scan] %s", err)
            return {
                "tool": "port_scan", "version": TOOL_INFO["version"],
                "target": target,
                "data": {"resolved_ip": None, "mode": mode, "ports_checked": 0,
                         "open_ports": [], "open_ports_details": [],
                         "open_count": 0, "scan_time": 0,
                         "source": "file", "threads_used": 0,
                         "load_metadata": load_metadata},
                "error": err,
            }
        ports_to_scan = file_ports
        ports_source = "file"
    else:
        ports_to_scan, load_metadata = load_basic_ports(folder_path)
        ports_source = load_metadata.get("source", "wordlist")
        logger.info("[port_scan] basic mode: %d ports (source=%s)",
                    len(ports_to_scan), ports_source)

    scanner = PortScanner(
        timeout=timeout, max_workers=max_workers,
        grab_banner=grab_banner, probe_tls=probe_tls, resolve_rdns=rdns,
        rate_limit=rate_limit, progress_cb=progress_cb,
    )

    try:
        results, elapsed, workers_used, resolved_ip, _fam = scanner.scan(host, ports_to_scan)

        # Optional reverse DNS on the host
        reverse_dns = None
        if rdns:
            try:
                reverse_dns = socket.gethostbyaddr(resolved_ip)[0]
            except Exception:
                reverse_dns = None

        open_results = [r for r in results if r.is_open]
        by_service: Dict[str, int] = {}
        for r in open_results:
            by_service[r.service] = by_service.get(r.service, 0) + 1

        data: Dict[str, Any] = {
            "resolved_ip":        resolved_ip,
            "reverse_dns":        reverse_dns,
            "mode":               mode,
            "ports_checked":      len(ports_to_scan),
            "open_ports":         [r.port for r in open_results],
            "open_ports_details": [r.to_dict() for r in open_results],
            "open_count":         len(open_results),
            "scan_time":          round(elapsed, 2),
            "source":             ports_source,
            "threads_used":       workers_used,
            "by_service":         by_service,
        }
        if mode == "basic":
            data["port_range"] = [
                min(ports_to_scan) if ports_to_scan else 0,
                max(ports_to_scan) if ports_to_scan else 0,
            ]
        if load_metadata:
            data["load_metadata"] = load_metadata

        return {
            "tool": "port_scan", "version": TOOL_INFO["version"],
            "target": target, "data": data, "error": None,
        }

    except socket.gaierror as e:
        return {
            "tool": "port_scan", "version": TOOL_INFO["version"],
            "target": target,
            "data": {"resolved_ip": None, "mode": mode, "ports_checked": 0,
                     "open_ports": [], "open_ports_details": [],
                     "open_count": 0, "scan_time": 0, "source": ports_source,
                     "threads_used": 0},
            "error": f"DNS resolution failed for '{host}': {e}",
        }
    except RuntimeError as e:
        return {
            "tool": "port_scan", "version": TOOL_INFO["version"],
            "target": target,
            "data": {"resolved_ip": None, "mode": mode,
                     "ports_checked": len(ports_to_scan),
                     "open_ports": [], "open_ports_details": [],
                     "open_count": 0, "scan_time": 0, "source": ports_source,
                     "threads_used": 0},
            "error": f"Thread allocation failed: {e}",
        }
    except Exception as e:
        logger.exception("[port_scan] unexpected failure: %s", e)
        return {
            "tool": "port_scan", "version": TOOL_INFO["version"],
            "target": target, "data": {}, "error": str(e),
        }


# ═══════════════════════════════════════════════════════════════════════════
# STREAMING API
# ═══════════════════════════════════════════════════════════════════════════
def run_streaming(target: str, mode: str = "basic",
                  options: Optional[Dict[str, Any]] = None,
                  cancel_event: Optional[Any] = None
                  ) -> Iterator[Dict[str, Any]]:
    options = options or {}
    started = time.time()
    yield {"type": "start", "target": target, "mode": mode}

    def _progress(done: int, total: int, port: int) -> None:
        pct = int((done / total) * 100) if total else 0
        events.append({"type": "progress", "done": done, "total": total,
                       "percent": pct, "port": port})

    events: List[Dict[str, Any]] = []
    holder: Dict[str, Any] = {}

    def _worker():
        try:
            holder["result"] = run(
                target, mode,
                timeout=float(options.get("timeout", DEFAULT_TIMEOUT)),
                max_workers=int(options.get("max_workers", DEFAULT_THREADS)),
                folder_path=options.get("folder_path"),
                banner=bool(options.get("banner", False)),
                tls=bool(options.get("tls", False)),
                rdns=bool(options.get("rdns", False)),
                rate_limit=float(options.get("rate_limit", RATE_LIMIT_DEFAULT)),
                progress_cb=_progress,
            )
        except Exception as e:
            holder["error"] = str(e)

    t = threading.Thread(target=_worker, daemon=True)
    t.start()
    while t.is_alive():
        if cancel_event is not None and hasattr(cancel_event, "is_set"):
            if cancel_event.is_set():
                yield {"type": "error", "message": "cancelled"}
                return
        while events:
            yield events.pop(0)
        t.join(timeout=0.3)
    while events:
        yield events.pop(0)
    if "error" in holder:
        yield {"type": "error", "message": holder["error"]}
    else:
        yield {"type": "result", "data": holder.get("result", {})}
    yield {"type": "summary",
           "duration_ms": int((time.time() - started) * 1000)}


# ═══════════════════════════════════════════════════════════════════════════
# EXPORTS
# ═══════════════════════════════════════════════════════════════════════════
def to_csv(result: Dict[str, Any]) -> str:
    buf = io.StringIO()
    w = csv.writer(buf)
    w.writerow(["port", "state", "service", "response_time", "banner"])
    for p in result.get("data", {}).get("open_ports_details", []):
        w.writerow([p.get("port"), p.get("state"), p.get("service"),
                    p.get("response_time"), p.get("banner", "")])
    return buf.getvalue()


def to_nmap_xml(result: Dict[str, Any]) -> str:
    """Very lightweight Nmap-style XML output."""
    d = result.get("data", {})
    host_ip = d.get("resolved_ip") or result.get("target", "")
    lines = ['<?xml version="1.0" encoding="UTF-8"?>',
             '<nmaprun scanner="oxysintx-port-scan" version="%s">' % TOOL_INFO["version"],
             f'  <host><address addr="{host_ip}" addrtype="ipv4"/>',
             '    <ports>']
    for p in d.get("open_ports_details", []):
        lines.append(
            f'      <port protocol="tcp" portid="{p["port"]}">'
            f'<state state="open"/>'
            f'<service name="{p.get("service", "unknown")}"/>'
            f'</port>'
        )
    lines += ['    </ports>', '  </host>', '</nmaprun>']
    return "\n".join(lines)


def to_sarif(result: Dict[str, Any]) -> Dict[str, Any]:
    findings = []
    for p in result.get("data", {}).get("open_ports_details", []):
        sev = "error" if p.get("port") in (21, 23, 445, 3389) else "note"
        findings.append({
            "ruleId": f"port/{p['port']}",
            "level": sev,
            "message": {"text": f"Open port {p['port']}/tcp — {p.get('service', 'unknown')}"},
        })
    return {
        "$schema": "https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json",
        "version": "2.1.0",
        "runs": [{"tool": {"driver": {"name": "Oxysintx Port Scan",
                                     "version": TOOL_INFO["version"]}},
                  "results": findings}],
    }


# ═══════════════════════════════════════════════════════════════════════════
# CLI
# ═══════════════════════════════════════════════════════════════════════════
def main() -> None:
    parser = argparse.ArgumentParser(description=TOOL_INFO["description"],
                                     formatter_class=argparse.ArgumentDefaultsHelpFormatter)
    parser.add_argument("target", nargs="?")
    parser.add_argument("-m", "--mode", choices=["basic", "expert"], default="basic")
    parser.add_argument("-t", "--timeout", type=float, default=DEFAULT_TIMEOUT)
    parser.add_argument("-w", "--workers", type=int, default=DEFAULT_THREADS)
    parser.add_argument("-f", "--folder", default=None)
    parser.add_argument("--range", dest="port_range", default=None)
    parser.add_argument("--banner", action="store_true", help="Grab service banner")
    parser.add_argument("--tls", action="store_true", help="TLS probe on TLS ports")
    parser.add_argument("--rdns", action="store_true", help="Reverse DNS on target")
    parser.add_argument("--rate-limit", type=float, default=RATE_LIMIT_DEFAULT)
    parser.add_argument("-o", "--output", help="Save result (json / csv / xml)")
    parser.add_argument("--format", choices=["json", "csv", "xml", "sarif"], default="json")
    parser.add_argument("-v", "--verbose", action="store_true")
    parser.add_argument("--validate", action="store_true")
    args = parser.parse_args()

    if args.verbose:
        logger.setLevel(logging.DEBUG)

    if args.validate:
        b_ports, b_meta = load_basic_ports(args.folder)
        e_ports, e_meta = load_ports_from_folder(args.folder)
        print("=" * 60)
        print(f"  Port Files Validation — v{TOOL_INFO['version']}")
        print("=" * 60)
        print(f"  Directory       : {b_meta['directory']}")
        print(f"  Basic files     : {b_meta['files_read']} ({len(b_ports)} ports)")
        print(f"  Expert files    : {e_meta['files_read']} ({len(e_ports)} ports)")
        print(f"  Basic source    : {b_meta.get('source', 'wordlist')}")
        print("=" * 60)
        sys.exit(0)

    if not args.target:
        parser.error("target is required (or use --validate)")

    result = run(
        args.target, mode=args.mode, timeout=args.timeout,
        max_workers=args.workers, folder_path=args.folder,
        verbose=args.verbose, banner=args.banner, tls=args.tls,
        rdns=args.rdns, rate_limit=args.rate_limit,
    )

    if args.output:
        with open(args.output, "w", encoding="utf-8") as f:
            if args.format == "csv":
                f.write(to_csv(result))
            elif args.format == "xml":
                f.write(to_nmap_xml(result))
            elif args.format == "sarif":
                json.dump(to_sarif(result), f, indent=2)
            else:
                json.dump(result, f, indent=2, default=str)
        print(f"Saved to {args.output}")
        return

    if result.get("error"):
        print(f"ERROR: {result['error']}")
        sys.exit(1)

    d = result.get("data", {})
    print("=" * 60)
    print(f"  Port Scan v{TOOL_INFO['version']}")
    print("=" * 60)
    print(f"  Target      : {result['target']}")
    print(f"  Resolved    : {d.get('resolved_ip', 'unknown')}")
    if d.get("reverse_dns"):
        print(f"  rDNS        : {d['reverse_dns']}")
    print(f"  Mode        : {d.get('mode')}")
    print(f"  Source      : {d.get('source')}")
    if d.get("port_range"):
        print(f"  Range       : {d['port_range'][0]}-{d['port_range'][1]}")
    print(f"  Checked     : {d.get('ports_checked', 0)} ports")
    print(f"  Open        : {d.get('open_count', 0)} found")
    print(f"  Time        : {d.get('scan_time', 0):.2f}s")
    print(f"  Threads     : {d.get('threads_used', 0)}")
    if d.get("by_service"):
        svc = ", ".join(f"{k}×{v}" for k, v in sorted(d["by_service"].items()))
        print(f"  Services    : {svc}")
    print("-" * 60)
    for p in d.get("open_ports_details", []):
        banner = f"  | {p['banner'][:40]}" if p.get("banner") else ""
        print(f"  {p['port']:5d}/tcp  {p['service']:14s}  {p['response_time']:.3f}s{banner}")
    if not d.get("open_ports_details"):
        print("  No open ports found.")
    print("=" * 60)


if __name__ == "__main__":
    main()